t_weight, ppk.box_weight, ppk.box_qty, pl.product_property_id, pd.charge_id, pi.iterate_ref_sku_id, pi.iterate_ref_sku_no, pd.warehouse_location, pd.warehouse_location_large FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id AND pd.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE LEFT JOIN product_sale ps ON ps.sku_id = pd."id" AND ps.is_deleted = FALSE LEFT JOIN product_pack ppk ON ppk.sku_id = pd."id" AND ppk.is_deleted = FALSE LEFT JOIN product_logistics pl ON pl.sku_id = pd."id" AND pl.is_deleted = FALSE LEFT JOIN product_unit unit ON pd.unit_id = unit.id AND unit.is_deleted = FALSE LEFT JOIN basic_dict dp ON pl.product_property_id = dp.id AND dp.is_deleted = FALSE WHERE pi.is_deleted = FALSE
