SELECT pd.version, pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pi.sale_method AS saleMethod, pd.sku_no, pi.spec_type, pd.images_url AS skuImagesUrl, pd.name AS skuName, pd.variant_property as variantProperty, pl.declare_chinese_name as declareName, pl.declare_model as declareModel, pl.product_property_id AS productPropertyId, pl.declare_currency_symbol as declareCurrencySymbol, pi.materials, pi.function_desc, pi.grade AS productGrade, pi.brand_name as brandName, ps.sale_state as saleState, pd.unit_name, pd.status, pp.moq, pp.main_supplier as supplierId, pc.actual_tax_cost, pc.target_tax_cost, pc.retail_price, ppk.product_length as productLength, ppk.product_width as productWidth, ppk.product_height as productHeight, pl.declare_element as declareElement, ppk.box_qty as boxQty, ppk.gross_weight as grossWeight, ppk.net_weight, pc.retail_price AS retailPrice FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id AND pl.is_deleted = FALSE left join product_sale ps on pd.id = ps.sku_id and ps.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE LEFT JOIN product_pack ppk ON ppk.sku_id = pd."id" AND ppk.is_deleted = FALSE WHERE pi.is_deleted = FALSE AND pd.is_deleted = FALSE
