SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.images_url AS skuImagesUrl, pd.name AS skuName, pd.variant_property, pp.box_qty as unitQty, pl.declare_chinese_name as declareName, pl.declare_model as declareModel, pd.unit_name FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_pack pp on pd.id = pp.sku_id AND pp.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id AND pl.is_deleted = FALSE WHERE pd.is_deleted = FALSE
AND pd.status=#{state}
AND ( pd.sku_no ILIKE concat('%',#{searchKeyword}::text,'%') OR pd.name ILIKE concat('%',#{searchKeyword}::text,'%') ) ORDER BY CASE WHEN pd.sku_no ILIKE concat('%',#{searchKeyword}::text,'%') THEN 1 WHEN pd.name ILIKE concat('%',#{searchKeyword}::text,'%') THEN 1 ELSE 2 END, LENGTH(pd.sku_no), LENGTH(pd.name), pd.sku_no, pd.name;

