SELECT pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.version, pd.id AS skuId, pd.sku_no, pd.images_url AS skuImagesUrl, pd.name AS skuName, pd.version, pd.unit_name, pd.status, pd.variant_property, pd.variant_property as variantProperty, pl.declare_chinese_name as declareName, pl.declare_model as declareModel, pl.product_property_id AS productPropertyId, pl.declare_element as declareElement, pl.declare_currency_symbol as declareCurrencySymbol, pi.spec_type, pi.materials, pi.function_desc, pi.grade AS productGrade, pi.brand_name as brandName, pi.category_id AS categoryId, ps.sale_state as saleState, pp.moq, pp.main_supplier as supplierId, pp.main_supplier as mainSupplier, pp.second_supplier as secondSupplier, pp.ean, pd.warehouse_location as warehouseLocation, pd.warehouse_location_large as warehouseLocationLarge, pi.sale_method, ppk.gross_weight, pc.actual_tax_cost, pc.target_tax_cost, pc.retail_price, ppk.product_length as productLength, ppk.product_width as productWidth, ppk.product_height as productHeight, ppk.box_qty as boxQty, ppk.box_qty as unitQty, ppk.net_weight FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id AND pl.is_deleted = FALSE left join product_sale ps on pd.id = ps.sku_id and ps.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE left join product_pack ppk on pd.id = ppk.sku_id AND ppk.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE WHERE pi.is_deleted = FALSE AND pd.is_deleted = FALSE
