SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.images_url AS skuImagesUrl, pd.name AS skuName, pd.variant_property, pp.box_qty as unitQty, pl.declare_chinese_name as declareName, pl.declare_model as declareModel, ppu.main_supplier, ppu.second_supplier, pd.unit_name FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_pack pp on pd.id = pp.sku_id AND pp.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id AND pl.is_deleted = FALSE left join product_purchase ppu on pd.id = ppu.sku_id AND ppu.is_deleted = FALSE WHERE pd.is_deleted = FALSE
AND pd.status = #{status}
AND (pd.sku_no = #{skuNo} OR ppu.ean = #{skuNo})
AND ( pd.sku_no ILIKE concat('%',#{searchKeyword}::text,'%') OR pd.name ILIKE concat('%',#{searchKeyword}::text,'%') ) ORDER BY CASE WHEN pd.sku_no ILIKE concat('%',#{searchKeyword}::text,'%') THEN 1 WHEN pd.name ILIKE concat('%',#{searchKeyword}::text,'%') THEN 1 ELSE 2 END, LENGTH(pd.sku_no), LENGTH(pd.name), pd.sku_no, pd.name;

SELECT pd.sku_no, pd.name AS skuName, pi.spu_no, pi.name AS spuName, pd.variant_property, pd.images_url, pp.ean, ppk.gross_weight, ppk.net_weight, ppk.product_length as productLength, ppk.product_width as productWidth, ppk.product_height as productHeight, ppk.box_length as boxLength, ppk.box_width as boxWidth, ppk.box_height as boxHeight, ppk.box_weight, ppk.box_qty, pi.grade, pd.charge_name, pi.materials, t.accessories, pp.main_supplier, pp.second_supplier FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE LEFT JOIN product_purchase pp ON pd.id = pp.sku_id AND pp.is_deleted = FALSE LEFT JOIN product_pack ppk ON pd.id = ppk.sku_id AND ppk.is_deleted = FALSE LEFT JOIN ( SELECT pa.parent_sku_id, array_to_string(ARRAY(SELECT unnest(array_agg(pd.sku_no))),',') AS accessories FROM product_accessories pa LEFT JOIN product_detail pd ON pa.accessories_sku_id = pd.id GROUP BY pa.parent_sku_id )t ON t.parent_sku_id = pd.id WHERE pd.is_deleted = FALSE
AND pd.sku_no = #{skuNo}
LIMIT 1

