AND pi.spu_no ILIKE concat('%',#{params.spuNo}::text,'%')
AND pl.declare_model ILIKE concat('%',#{params.declareModel}::text,'%')
AND pl.declare_element ILIKE concat('%',#{params.declareElement}::text,'%')
