SELECT pd.sku_no AS skuNo, pd.id AS skuId, pd.id AS id, pd.name AS productName, pi.spu_no AS spuNo, sl.operation AS operate, sl.content AS operateContent, sl.create_user_name AS operateUserName, sl.create_time AS operateTime FROM sys_log sl LEFT JOIN product_detail pd ON sl.business_id = pd.id AND pd.is_deleted = FALSE LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE WHERE sl.is_deleted=FALSE AND pd.status=#{approveStatus} AND sl.field_name IN
#{item}
AND pd.sku_no IN
#{item}
AND pi.spu_no ILIKE concat('%',#{params.spuNo}::text,'%')
AND sl.operation ILIKE concat('%',#{params.operate}::text,'%')
AND pd.name ILIKE concat('%',#{params.productName}::text,'%')
AND sl.content ILIKE concat('%',#{params.operateContent}::text,'%')
AND sl.create_user_id =#{params.operateUserId}
AND sl.create_time >= #{params.operateTimeList[0]} and (#{params.operateTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sl.create_time
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sl.create_time DESC

