#{item}
${permissionSql}

SELECT pl.sku_id,pl.product_property,pl.product_property_id,pl.declare_chinese_name,pl.declare_english_name, pl.declare_price,pl.customs_code,pl.declare_element,pl.english_material,pl.english_usage, pl.create_time,pl.create_user_id,pl.update_time,pl.update_user_id,pl.create_user_name,pl.update_user_name, pl.declare_model,pl.declare_unit,pl.declare_currency,pl.declare_currency_symbol,pl.dest_declare_price, pl.dest_currency,pl.dest_currency_symbol,pl.source_cargo,pl.exemption,pl.source_country, pl.combination_declare_type,pd.sku_no as skuNo, pp.gross_weight as grossWeight, pp.box_length / 10 AS boxSizeLength, pp.box_width / 10 AS boxSizeWide, pp.box_height / 10 AS boxSizeHigh, pp.product_length as productLength,pp.product_width as productWidth,pp.product_height as productHeight, (select value from basic_dict where is_deleted=false and id=pl.product_property_id LIMIT 1) AS productProperty, (select name from basic_dict where is_deleted=false and value=pl.declare_unit and type ='declareUnit' LIMIT 1) AS declareUnitName, pd.name as cnName,pd.name_en as enName, pi.spu_no as spuNo, pl.first_qty as firstQty, pl.second_qty as secondQty, pl.approve_status as approveStatus, pd.images_url as imagesUrl FROM product_detail pd LEFT join product_logistics pl on pl.sku_id = pd.id and pl.is_deleted = false LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_pack pp on pp.sku_id = pl.sku_id and pp.is_deleted = false WHERE pd.is_deleted=false
AND pd.id IN
#{item}
AND pd.sku_no IN
#{item}

SELECT pd.ID AS skuId, pi.ID AS productId,
pd.sku_no,
CASE WHEN pbi."type" IS NULL OR pbi."type" = 'single' THEN false ELSE true END AS is_combination FROM product_detail pd LEFT JOIN product_info pi ON pi.ID = pd.product_id AND pi.is_deleted = FALSE LEFT JOIN (SELECT parent_sku_id,MAX(id) AS min_id,bom_id FROM product_bom_sku WHERE is_deleted = FALSE GROUP BY parent_sku_id, bom_id) AS pbs on pd.id = pbs.parent_sku_id LEFT JOIN product_bom_info pbi on pbi.id = pbs.bom_id and pbi.is_deleted = false and pbi."state" =4 WHERE pd.is_deleted = FALSE
AND pd.status=#{state}
AND ( pd.sku_no ILIKE concat('%',#{searchKeyword}::text,'%') OR pd.name ILIKE concat('%',#{searchKeyword}::text,'%') ) ORDER BY CASE WHEN pd.sku_no ILIKE concat('%',#{searchKeyword}::text,'%') THEN 1 WHEN pd.name ILIKE concat('%',#{searchKeyword}::text,'%') THEN 1 ELSE 2 END, LENGTH(pd.sku_no), LENGTH(pd.name), pd.sku_no, pd.name;

